60	const PersistentDetails: FC<{
61		summary: ReactNode;
62		stateKey: string;
63		viewState?: ViewState;
64		onViewStateChange?: ViewStateChange;
65		children: ReactNode;
66		className?: string;
67	}> = ({
68		summary,
69		stateKey,
70		viewState = {},
71		onViewStateChange,
72		children,
73		className,
74	}) => {
75		const restored = viewState[stateKey];
76		const [localOpen, setLocalOpen] = useState(restored === true);
77		useEffect(() => {
78			setLocalOpen(restored === true);
79		}, [restored]);
80		const open = typeof restored === "boolean" ? restored : localOpen;
81		return (
82			<div className={className}>
83				<button
84					type="button"
85					aria-expanded={open}
86					className="flex w-full cursor-pointer items-center gap-1.5 text-left font-medium"
87					onClick={() => {
88						const next = !open;
89						setLocalOpen(next);
90						onViewStateChange?.(stateKey, next);
91					}}
92				>
93					<span aria-hidden="true">{open ? "▾" : "▸"}</span>
94					<span className="min-w-0 flex-1 truncate">{summary}</span>
95				</button>
96				{open ? children : null}
97			</div>
98		);
