378	const METADATA_PREVIEW_LIMIT = 3;
379	
380	/** Show a few scalar metadata fields inline; reveal the rest on expand. */
381	const EntityMetadataPreview: FC<{
382		metadata: UnknownRecord;
383		openLink: (href: string) => void;
384		stateKey: string;
385		viewState?: ViewState;
386		onViewStateChange?: ViewStateChange;
387	}> = ({ metadata, openLink, stateKey, viewState, onViewStateChange }) => {
388		const entries = Object.entries(metadata).filter(
389			([, value]) => value !== null && value !== undefined,
390		);
391		const scalar = entries.filter(([, value]) => isScalar(value));
392		const structured = entries.filter(([, value]) => !isScalar(value));
393		const restored = viewState?.[`${stateKey}.metadata.open`];
394		const [localOpen, setLocalOpen] = useState(restored === true);
395		if (scalar.length === 0 && structured.length === 0) return null;
396		const preview = scalar.slice(0, METADATA_PREVIEW_LIMIT);
397		const hiddenCount = scalar.length - preview.length + structured.length;
398		const expanded = typeof restored === "boolean" ? restored : localOpen;
399		const rows = expanded ? [...scalar, ...structured] : preview;
400		if (rows.length === 0) return null;
401		const toggle = (next: boolean) => {
402			setLocalOpen(next);
403			onViewStateChange?.(`${stateKey}.metadata.open`, next);
404		};
405		return (
406			<div className="mt-2">
407				<dl className="grid grid-cols-[minmax(5rem,0.35fr)_1fr] gap-1 text-xs">
408					{rows.map(([key, value]) => (
409						<Fragment key={key}>
410							<dt className="break-words font-medium text-muted-foreground">
411								{humanize(key)}
412							</dt>
413						<dd className="min-w-0">
414							{isScalar(value) ? (
415								<LinkValue value={String(value)} openLink={openLink} />
416							) : expanded ? (
417								<ValueView
418									value={value}
419									openLink={openLink}
420									depth={1}
421									stateKey={`${stateKey}.metadata.${key}`}
422									viewState={viewState}
423									onViewStateChange={onViewStateChange}
424								/>
425							) : (
426								<button
427									type="button"
428									className="cursor-pointer text-primary underline"
429									onClick={() => toggle(true)}
430								>
431									{Array.isArray(value) ? "[…]" : "{…}"}
432								</button>
433							)}
434						</dd>
435						</Fragment>
436					))}
437				</dl>
438				{!expanded && hiddenCount > 0 ? (
439					<button
440						type="button"
441						className="mt-1 cursor-pointer font-medium text-primary"
442						onClick={() => toggle(true)}
443					>
444						Show {hiddenCount} more {hiddenCount === 1 ? "field" : "fields"}
445					</button>
446				) : null}
447				{expanded && hiddenCount > 0 ? (
448					<button
449						type="button"
450						className="mt-1 cursor-pointer font-medium text-primary"
451						onClick={() => toggle(false)}
452					>
453						Show less
454					</button>
455				) : null}
456			</div>
457		);
458	};
