460	function Pagination({
461		page,
462		pageCount,
463		onChange,
464	}: {
465		page: number;
466		pageCount: number;
467		onChange: (page: number) => void;
468	}) {
469		return (
470			<div className="mt-2 flex items-center justify-end gap-1.5">
471				<Button
472					type="button"
473					size="sm"
474					variant="outline"
475					disabled={page === 0}
476					onClick={() => onChange(page - 1)}
477				>
478					<ChevronLeft className="h-3.5 w-3.5" />
479					<span className="sr-only">Previous page</span>
480				</Button>
481				<span className="text-muted-foreground text-xs">
482					{page + 1} / {pageCount}
483				</span>
484				<Button
485					type="button"
486					size="sm"
487					variant="outline"
488					disabled={page + 1 >= pageCount}
489					onClick={() => onChange(page + 1)}
490				>
491					<ChevronRight className="h-3.5 w-3.5" />
492					<span className="sr-only">Next page</span>
493				</Button>
494			</div>
495		);
496	}
497	
498	const ValueList: FC<{
499		values: unknown[];
500		openLink: (href: string) => void;
501		depth: number;
502		stateKey: string;
503		viewState?: ViewState;
504		onViewStateChange?: ViewStateChange;
505	}> = ({ values, openLink, depth, stateKey, viewState, onViewStateChange }) => {
506		const pageSize = 10;
507		const restoredPage = viewState?.[`${stateKey}.page`];
508		const [localPage, setLocalPage] = useState(
509			typeof restoredPage === "number" ? Math.max(0, restoredPage) : 0,
510		);
511		useEffect(() => {
512			setLocalPage(
513				typeof restoredPage === "number" ? Math.max(0, restoredPage) : 0,
514			);
515		}, [restoredPage]);
516		const pageCount = Math.max(1, Math.ceil(values.length / pageSize));
517		const requestedPage =
518			typeof restoredPage === "number" ? Math.max(0, restoredPage) : localPage;
519		const page = Math.min(requestedPage, pageCount - 1);
520		const changePage = (next: number) => {
521			setLocalPage(next);
522			onViewStateChange?.(`${stateKey}.page`, next);
523		};
524		const visible = values.slice(page * pageSize, (page + 1) * pageSize);
525		return (
526			<div>
527				<div className="space-y-2">
528					{visible.map((item, index) => (
529						// biome-ignore lint/suspicious/noArrayIndexKey: arbitrary result arrays may contain duplicate, identity-less values and are immutable here.
530						<div key={`${page}:${index}:${compactValue(item).slice(0, 30)}`}>
531							<ValueView
532								value={item}
533								openLink={openLink}
534								depth={depth + 1}
535								stateKey={`${stateKey}.${page * pageSize + index}`}
536								viewState={viewState}
537								onViewStateChange={onViewStateChange}
538							/>
539						</div>
540					))}
541				</div>
542				{pageCount > 1 ? (
543					<Pagination page={page} pageCount={pageCount} onChange={changePage} />
544				) : null}
545			</div>
546		);
547	};
548	
549	/** Keep short scalars always visible; everything else is collapsed by default. */
550	const SHORT_SCALAR_LIMIT = 90;
551	
552	function isShortScalar(value: unknown): boolean {
553		if (value === null || typeof value === "number" || typeof value === "boolean") {
554			return true;
555		}
556		if (typeof value === "string") {
557			return value.length <= SHORT_SCALAR_LIMIT && !value.includes("\n");
558		}
559		return false;
560	}
561	
562	function fieldSummary(key: string, value: unknown): string {
563		const label = humanize(key);
564		if (Array.isArray(value)) {
565			const n = value.length;
566			return `${label} · ${n} ${n === 1 ? "item" : "items"}`;
567		}
568		if (isRecord(value)) {
569			const n = Object.keys(value).length;
570			return `${label} · ${n} ${n === 1 ? "field" : "fields"}`;
571		}
572		if (typeof value === "string") {
573			// Prefer the first line only — joining the whole multi-line blob into the
574			// summary would leak later lines while the section is still collapsed.
575			const firstLine = (value.split(/\r?\n/, 1)[0] ?? "").replace(/\s+/g, " ").trim();
576			if (!firstLine) return label;
577			const preview =
578				firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine;
579			return `${label} · ${preview}`;
580		}
581		return label;
582	}
583	
584	const ValueView: FC<{
585		value: unknown;
586		openLink: (href: string) => void;
587		depth?: number;
588		stateKey?: string;
589		viewState?: ViewState;
590		onViewStateChange?: ViewStateChange;
591	}> = ({
592		value,
593		openLink,
594		depth = 0,
595		stateKey = "value",
596		viewState,
597		onViewStateChange,
598	}) => {
599		if (typeof value === "string") {
600			// Long / multi-line strings as a whole return value (not nested under a
601			// field collapsible) stay compact until opened.
602			if (!isShortScalar(value)) {
603				return (
604					<PersistentDetails
605						summary={fieldSummary("value", value).replace(/^Value · /, "")}
606						stateKey={`${stateKey}.text.open`}
607						viewState={viewState}
608						onViewStateChange={onViewStateChange}
609						className="text-xs text-muted-foreground"
610					>
611						<div className="mt-2 text-foreground">
612							<LinkValue value={value} openLink={openLink} />
613						</div>
614					</PersistentDetails>
615				);
616			}
617			return <LinkValue value={value} openLink={openLink} />;
618		}
619		if (value === null || value === undefined || typeof value !== "object") {
620			return <span className="break-words text-sm">{compactValue(value)}</span>;
621		}
622		if (depth >= 5) {
623			return (
624				<pre className="overflow-x-auto whitespace-pre-wrap text-xs">
625					{stringify(value)}
626				</pre>
627			);
628		}
629		if (Array.isArray(value)) {
630			if (value.length === 0)
631				return <span className="text-muted-foreground text-xs">Empty</span>;
632			const records = value.filter(isRecord);
633			if (
634				records.length === value.length &&
635				records.every((record) => looksLikeEntity(record))
636			) {
637				const entityRows = records.map((entity) => {
638					const metadata = isRecord(entity.metadata) ? entity.metadata : null;
639					const link = [entity.view_url, entity.url, entity.source_url].find(
640						isExternalHttpUrl,
641					);
642					return {
643						name: entity.name,
644						type: humanize(
645							String(
646								entity.entity_type ??
647									entity.entity_type_name ??
648									entity.type ??
649									"Entity",
650							),
651						),
652						id: entity.id,
653						...(metadata && Object.keys(metadata).length > 0 ? { metadata } : {}),
654						...(link ? { open: link } : {}),
655					};
656				});
657				const entityColumns = ["name", "type", "id"];
658				if (entityRows.some((row) => "metadata" in row)) {
659					entityColumns.push("metadata");
660				}
