884	function parseSdkMethodDoc(value: string): SdkMethodDoc {
885		const lines = value.split("\n");
886		const listParts = lines[0]?.split(/\s+—\s+/, 2) ?? [];
887		const path = (listParts[0] ?? "SDK method").trim();
888		const detailLines = lines
889			.slice(1)
890			.map((line) => line.trim())
891			.filter(Boolean);
892		const accessLine = detailLines.find((line) => line.startsWith("access:"));
893		const summary =
894			listParts[1]?.trim() ||
895			detailLines.find(
896				(line) =>
897					!line.startsWith("access:") &&
898					!line.startsWith("signature:") &&
899					!line.startsWith("example:") &&
900					line !== "usage_example:",
901			) ||
902			"SDK method";
903		const details = detailLines.filter(
904			(line) => line !== summary && !line.startsWith("access:"),
905		);
906		return {
907			path,
908			namespace: path.includes(".") ? path.split(".")[0] : "Related",
909			summary,
910			access: accessLine?.slice("access:".length).trim().split(" ")[0],
911			details,
912		};
913	}
