/**
 * `save_memory` returns a write receipt, not content: `{id, title,
 * semantic_type, created_at, indexing_status, searchable, entity_ids,
 * view_url, exact_read, …}`. It satisfies `looksLikeEvent` (semantic_type plus
 * id), so without this branch it rendered through `EventView` as a card whose
 * body read "No event payload." — the one shape where the generic walk is not
 * merely bulky but actively wrong. What a reader needs is what was written,
 * whether it is searchable yet, and where to open it.
 */
function isSaveReceipt(value: UnknownRecord): boolean {
	return (
		typeof value.id === "number" &&
		typeof value.semantic_type === "string" &&
		typeof value.created_at === "string" &&
		typeof value.searchable === "boolean" &&
		(value.indexing_status === "pending" ||
			value.indexing_status === "completed")
	);
}

/** Keys the receipt header already states; the rest stays under one toggle. */
const RECEIPT_HEADER_KEYS = new Set([
	"id",
	"title",
	"semantic_type",
	"created_at",
