/** Fields whose short string value reads as the result's own sentence. */
const HEADLINE_KEYS = ["summary", "message", "note", "status", "title"];
const SUMMARY_FACT_LIMIT = 3;
const PEEK_LINE_CLAMP = "line-clamp-3";

/** A long string shown three lines deep, expandable in place. */
const PeekText: FC<{
	label: string;
	value: string;
	stateKey: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ label, value, stateKey, viewState, onViewStateChange }) => {
	const restored = viewState?.[stateKey];
	const [localOpen, setLocalOpen] = useState(restored === true);
	useEffect(() => {
		setLocalOpen(restored === true);
	}, [restored]);
	const open = typeof restored === "boolean" ? restored : localOpen;
	return (
		<div className="rounded-md border-border/70 border-l-2 bg-muted/40 px-2.5 py-2">
			<div className="text-muted-foreground text-xs">{label}</div>
			<p
				className={cn(
					"mt-0.5 whitespace-pre-wrap break-words text-sm",
					open ? null : PEEK_LINE_CLAMP,
				)}
			>
				{value}
			</p>
			<button
				type="button"
				className="mt-1 cursor-pointer font-medium text-primary text-xs"
				onClick={() => {
					const next = !open;
					setLocalOpen(next);
					onViewStateChange?.(stateKey, next);
				}}
			>
				{open ? "Show less" : "Show more"}
			</button>
		</div>
	);
};

/**
 * Top-level presentation for an arbitrary return value.
 *
 * `ValueView` keeps the mechanical rule at every depth — short scalars inline,
 * everything bulky collapsed — which bounds the card but hides the answer along
 * with the noise. At the top level two things are promoted instead: the field
 * that reads as the result's own sentence, and the single bulky string that
 * usually *is* the result (an error, a report, a diagnostic). The remainder
 * goes behind one toggle rather than one toggle per field.
 *
 * When there is nothing to promote this defers to `ValueView` unchanged, so the
 * collapse rule stays the floor rather than being replaced by a guess.
 */
const TopLevelValue: FC<{
	value: unknown;
	openLink: (href: string) => void;
	stateKey: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, openLink, stateKey, viewState, onViewStateChange }) => {
	const fallback = (
		<ValueView
			value={value}
			openLink={openLink}
			stateKey={stateKey}
			viewState={viewState}
			onViewStateChange={onViewStateChange}
		/>
	);
	if (!isRecord(value)) return fallback;
	const entries = Object.entries(value).filter(
		([, inner]) => inner !== undefined,
	);
	const headlineKey = HEADLINE_KEYS.find((key) => {
		const inner = value[key];
		return (
			typeof inner === "string" && isShortScalar(inner) && inner.trim() !== ""
		);
	});
	const longStrings = entries.filter(
		([, inner]) => typeof inner === "string" && !isShortScalar(inner),
	);
	// Two or more bulky strings give no basis for choosing one, so none is
	// promoted — they all stay behind their own toggles under Details.
	const peek = longStrings.length === 1 ? longStrings[0] : null;
	if (!headlineKey && !peek) return fallback;
	const facts = entries
		.filter(([key, inner]) => key !== headlineKey && isShortScalar(inner))
		.slice(0, SUMMARY_FACT_LIMIT);
	const promoted = new Set<string>([
		...(headlineKey ? [headlineKey] : []),
		...(peek ? [peek[0]] : []),
		...facts.map(([key]) => key),
	]);
	const rest = entries.filter(([key]) => !promoted.has(key));
	return (
		<div className="space-y-2">
			{headlineKey ? (
				<p className="font-medium text-sm">{String(value[headlineKey])}</p>
			) : null}
			{peek ? (
				<PeekText
					label={humanize(peek[0])}
					value={peek[1] as string}
					stateKey={`${stateKey}.${peek[0]}.peek`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
				/>
			) : null}
			{facts.length > 0 ? (
				<dl className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-1 text-xs">
					{facts.map(([key, inner]) => (
						<Fragment key={key}>
							<dt className="break-words font-medium text-muted-foreground">
								{humanize(key)}
							</dt>
							<dd className="min-w-0">
								{typeof inner === "string" ? (
									<LinkValue value={inner} openLink={openLink} />
								) : (
									<span className="break-words text-sm">
										{compactValue(inner)}
									</span>
								)}
							</dd>
						</Fragment>
					))}
				</dl>
			) : null}
			{rest.length > 0 ? (
				<PersistentDetails
					summary={`Details · ${rest.length} ${
						rest.length === 1 ? "field" : "fields"
					}`}
					stateKey={`${stateKey}.details.open`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					className="text-xs text-muted-foreground"
				>
					<div className="mt-2 text-foreground">
						<ValueView
							value={Object.fromEntries(rest)}
							openLink={openLink}
							depth={1}
							stateKey={stateKey}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					</div>
				</PersistentDetails>
			) : null}
		</div>
	);
};

