/**
 * Disclosure state for one togglable region. A host-restored value always wins
 * so a rehydrated card reopens exactly what the reader had open; otherwise the
 * local state applies. Every toggle also reports back so the state survives the
 * next restore.
 */
function useDisclosure(
	stateKey: string,
	viewState: ViewState | undefined,
	onViewStateChange: ViewStateChange | undefined,
): [boolean, (next: boolean) => void] {
	const restored = viewState?.[stateKey];
	const [localOpen, setLocalOpen] = useState(restored === true);
	useEffect(() => {
		setLocalOpen(restored === true);
	}, [restored]);
	const open = typeof restored === "boolean" ? restored : localOpen;
	return [
		open,
		(next: boolean) => {
			setLocalOpen(next);
			onViewStateChange?.(stateKey, next);
		},
	];
}

const PersistentDetails: FC<{
	summary: ReactNode;
	stateKey: string;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
	children: ReactNode;
	className?: string;
}> = ({
	summary,
	stateKey,
	viewState,
	onViewStateChange,
	children,
	className,
}) => {
	const [open, setOpen] = useDisclosure(stateKey, viewState, onViewStateChange);
	return (
		<div className={className}>
			<button
				type="button"
				aria-expanded={open}
				className="flex w-full cursor-pointer items-center gap-1.5 text-left font-medium"
