function isShortScalar(value: unknown): boolean {
	if (value === null || typeof value === "number" || typeof value === "boolean") {
		return true;
	}
	if (typeof value === "string") {
		return value.length <= SHORT_SCALAR_LIMIT && !value.includes("\n");
	}
	return false;
}

/** An array or object with nothing in it. */
function isEmptyStructure(value: unknown): boolean {
	if (Array.isArray(value)) return value.length === 0;
	return isRecord(value) && Object.keys(value).length === 0;
}

/**
 * What can be stated on one line rather than hidden behind a disclosure.
 *
 * Empty arrays and objects belong here even though they are structures: a
 * `Rows · 0 items` toggle is a control that reveals nothing when opened, so it
 * costs the reader a click to learn what the summary already said.
 */
function isInlineValue(value: unknown): boolean {
	return isShortScalar(value) || isEmptyStructure(value);
}

/** How an inline value reads in the value column. */
function inlineText(value: unknown): string {
	if (Array.isArray(value)) return "None";
	if (isRecord(value)) return "None";
	return compactValue(value);
}

