/**
 * TIER 1 — the script declared its own presentation.
 *
 * This is the same `{payload_type, payload_template, payload_data}` triple that
 * `EventView` already renders for stored event templates, recognised at the top
 * of a tool return. No new card language: a declaring script gets the metric,
 * table, alert, and chart nodes the template renderer already ships.
 *
 * Checked before `looksLikeEvent`, which fires on the presence of
 * `payload_type` alone once a script also sets `title` — another instance of the
 * ordering hazard that tool-name dispatch would remove outright.
 */
function declaredTemplate(
	value: UnknownRecord,
): { root: McpJsonNode; data: UnknownRecord } | null {
	if (value.payload_type !== "json_template") return null;
	const template = isRecord(value.payload_template)
		? value.payload_template
		: null;
	if (!isRecord(template?.root)) return null;
	return {
		root: template.root as McpJsonNode,
		data: isRecord(value.payload_data) ? value.payload_data : {},
	};
}

const DeclaredView: FC<{
	declared: { root: McpJsonNode; data: UnknownRecord };
	value: UnknownRecord;
	openLink: (href: string) => void;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ declared, value, openLink, viewState, onViewStateChange }) => {
	const sourceUrl =
		typeof value.source_url === "string" && isExternalHttpUrl(value.source_url)
			? value.source_url
			: null;
	// Actions resolve by name against this map, never by anything the script
	// supplies directly — a declared template may reference `@open`, it cannot
	// introduce a handler.
	const actions = sourceUrl
		? { open: () => openLink(sourceUrl), openSource: () => openLink(sourceUrl) }
		: undefined;
	const rest = Object.entries(value).filter(
		([key]) =>
			!["payload_type", "payload_template", "payload_data", "source_url"].includes(
				key,
			),
	);
	return (
		<div className="space-y-2">
			<Section>
				<McpJsonTemplateView
					template={{ root: declared.root }}
					data={declared.data}
					openLink={openLink}
					actions={actions}
				/>
			</Section>
			{rest.length > 0 ? (
				<PersistentDetails
					summary={`Result data · ${rest.length} ${
						rest.length === 1 ? "field" : "fields"
					}`}
					stateKey="details.declared-rest.open"
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					className="text-xs text-muted-foreground"
				>
					<div className="mt-2 text-foreground">
						<ValueView
							value={Object.fromEntries(rest)}
							openLink={openLink}
							depth={1}
							stateKey="declared.rest"
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					</div>
				</PersistentDetails>
			) : null}
		</div>
	);
};

/**
 * TIER 3 — nothing worth drawing a card around.
 *
 * A result has substance when it carries something prose is bad at: rows to
 * scan, entities to open, an error to read, a template the author declared. A
 * bag of short scalars is not that — the model has already said it better in
 * the sentence above the card, so a bordered box with disclosures is a second,
 * worse copy. State it in one line and keep the data one click away.
 */
function hasSubstance(value: unknown): boolean {
	if (typeof value === "string") return !isShortScalar(value);
	if (Array.isArray(value)) return value.some(isRecord);
	if (!isRecord(value)) return false;
	if (declaredTemplate(value)) return true;
	if (looksLikeEvent(value) || looksLikeEntity(value)) return true;
	if (isSaveReceipt(value) || isSqlResult(value)) return true;
	if (value.error !== undefined && value.error !== null) return true;
	for (const inner of Object.values(value)) {
		if (Array.isArray(inner) && inner.some(isRecord)) return true;
		if (typeof inner === "string" && !isShortScalar(inner)) return true;
		if (isRecord(inner) && hasSubstance(inner)) return true;
	}
	return false;
}

