	value: unknown;
	meta?: string;
	openLink: (href: string) => void;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, meta, openLink, viewState, onViewStateChange }) => {
	const fieldCount = isRecord(value) ? Object.keys(value).length : 0;
	const summary = [
		fieldCount > 0
			? `${fieldCount} ${fieldCount === 1 ? "field" : "fields"}`
			: "No return value",
		meta,
	]
		.filter(Boolean)
		.join(" · ");
	return (
		<PersistentDetails
			summary={
				<span className="text-muted-foreground">
					<CheckCircle2 className="mr-1 inline h-3.5 w-3.5 text-green-600" />
					{summary}
