}> = ({ query, viewState, onViewStateChange }) => {
	// useDisclosure, not a bare viewState read: without the local fallback this
	// toggle is inert in any host that does not persist view state back to us.
	const [open, setOpen] = useDisclosure(
		"details.sql-query.open",
		viewState,
		onViewStateChange,
	);
	const trimmed = query.trim();
	return (
		<div className="mt-2 text-xs">
			{/* The SQL is provenance, not the answer. It opens on demand rather than
			    taking the top of the card ahead of the rows it produced. */}
			<button
				type="button"
				aria-expanded={open}
				className="flex cursor-pointer items-center gap-1 font-medium text-primary"
				onClick={() => setOpen(!open)}
			>
				<span aria-hidden="true">{open ? "▾" : "▸"}</span>
				{open ? "Hide query" : "Show query"}
			</button>
			{open ? (
				<code className="mt-1 block min-w-0 whitespace-pre-wrap break-words font-mono text-foreground/80">
					{trimmed}
				</code>
			) : null}

