SCRIPT=$(cat <<'EOF'
export default async (ctx, client) => {
  const CHROME = 479;
  const PHASE = "__PHASE__";
  const BASE = "http://127.0.0.1:4181/mcp-app-harness.html?case=";
  const CASES = ["single-entity","sql","sql-zero-rows","sql-error","generic-allowlist-error"];
  const findDataUrl = (o) => {
    if (typeof o === "string") return o.startsWith("data:image") ? o : null;
    if (Array.isArray(o)) { for (const v of o) { const r = findDataUrl(v); if (r) return r; } return null; }
    if (o && typeof o === "object") { for (const v of Object.values(o)) { const r = findDataUrl(v); if (r) return r; } }
    return null;
  };
  const nav = await client.operations.execute({ connection_id: CHROME, operation_key: "navigate",
    input: { url: BASE + CASES[0], open_in_new_tab: true, wait_for_load: true } });
  const tab = nav.output.tab_id;
  const out = [];
  for (const c of CASES) {
    await client.operations.execute({ connection_id: CHROME, operation_key: "navigate",
      input: { tab_id: tab, url: BASE + c, wait_for_load: true } });
    const probe = await client.operations.execute({ connection_id: CHROME, operation_key: "evaluate",
      input: { tab_id: tab, await_promise: true,
        expression: "(async()=>{await new Promise(r=>setTimeout(r,1500));return document.body.innerText.replace(/\\s+/g,' ').slice(0,100)})()" } });
    const shot = await client.operations.execute({ connection_id: CHROME, operation_key: "screenshot", input: { tab_id: tab } });
    const url = findDataUrl(shot.output);
    if (!url) { out.push({ c, err: "no data_url" }); continue; }
    const post = await client.operations.execute({ connection_id: CHROME, operation_key: "evaluate",
      input: { tab_id: tab, await_promise: true,
        expression: "fetch('http://127.0.0.1:5200/?name=" + PHASE + "-" + c + "',{method:'POST',body:" + JSON.stringify(JSON.stringify(url)) + "}).then(r=>r.status)" } });
    out.push({ c, bytes: url.length, post: JSON.stringify(post.output).slice(0, 40), text: probe.output });
  }
  await client.operations.execute({ connection_id: CHROME, operation_key: "close_tab", input: { tab_id: tab } });
  return out;
};
EOF
)
