it("keeps the caller's title on the empty and failed paths", () => {
	// query_sql spreads `title` into every return including fail(), so the
	// heading is available exactly when the reader needs to know WHICH query
	// came back empty. The empty branch used to drop it.
	const base = {
		sql: "SELECT id FROM invoices WHERE due < now()",
		rows: [],
		columns: [{ name: "id", type: "integer" }],
		total_count: 0,
		has_more: false,
		execution_time_ms: 6,
		title: "Overdue invoices",
	};
	const { unmount } = render(
		<McpResultView
			toolName="query_sql"
			value={base}
			onAction={() => undefined}
			openLink={() => undefined}
		/>,
	);
	expect(screen.getByText("Overdue invoices")).toBeInTheDocument();
	expect(screen.queryByText("Executed query")).not.toBeInTheDocument();
	unmount();

	render(
		<McpResultView
			toolName="query_sql"
			value={{ ...base, error: "permission denied for table invoices" }}
			onAction={() => undefined}
			openLink={() => undefined}
		/>,
	);
	expect(screen.getByText("Overdue invoices")).toBeInTheDocument();
	expect(
		screen.getByText("permission denied for table invoices"),
	).toBeInTheDocument();
});

